package render

import (
	"fmt"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"

	"github.com/hayone1/gitopsify/pkg/yamlutil"
)

// Tree is an in-memory directory of generated files, keyed by slash path.
type Tree struct {
	files map[string][]byte
	// roots are directories that are repositories of their own (one per
	// environment): each gets the manifest of its files, so a checkout of
	// that repository alone knows what an earlier run generated.
	roots []string
}

// NewTree returns an empty tree.
func NewTree() *Tree { return &Tree{files: map[string][]byte{}} }

// Add stores a file, replacing any previous content.
func (t *Tree) Add(p string, data []byte) { t.files[path.Clean(p)] = data }

// AddYAML stores one or more objects as a YAML stream.
func (t *Tree) AddYAML(p string, objs ...any) error {
	b, err := yamlutil.MarshalDocs(objs...)
	if err != nil {
		return fmt.Errorf("%s: %w", p, err)
	}
	t.Add(p, b)
	return nil
}

// Get returns a file's content.
func (t *Tree) Get(p string) ([]byte, bool) {
	b, ok := t.files[path.Clean(p)]
	return b, ok
}

// Paths returns all file paths, sorted.
func (t *Tree) Paths() []string {
	out := make([]string, 0, len(t.files))
	for p := range t.files {
		out = append(out, p)
	}
	sort.Strings(out)
	return out
}

// manifestFile lists the files of the previous generation so a regeneration
// can remove files that are no longer produced without touching files people
// added by hand.
const manifestFile = ".gitopsify/generated.txt"

// Write writes the tree under dir. Files listed in the previous generation's
// manifest but not produced now are removed. Without force, Write refuses to
// overwrite a non-empty directory that was not generated by gitopsify.
//
// Paths come partly from the cluster (Helm release files): each must stay
// inside dir and out of .git, and everything goes through an os.Root, so a
// symlink in a cloned output directory can't lead elsewhere either.
func (t *Tree) Write(dir string, force bool) (written, removed []string, err error) {
	paths := t.Paths()
	for _, p := range paths {
		if err := treePath(p); err != nil {
			return nil, nil, err
		}
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, nil, err
	}
	root, err := os.OpenRoot(dir)
	if err != nil {
		return nil, nil, err
	}
	defer root.Close()
	prev := map[string]bool{}
	readManifest := func(file, prefix string) bool {
		data, err := root.ReadFile(file)
		if err != nil {
			return false
		}
		for _, l := range strings.Split(string(data), "\n") {
			// The manifest comes from the output directory, which may be a
			// cloned repository: never let it name files outside of it.
			if l = strings.TrimSpace(l); l != "" && treePath(l) == nil {
				prev[path.Join(prefix, path.Clean(l))] = true
			}
		}
		return true
	}
	found := readManifest(manifestFile, "")
	for _, r := range t.roots {
		found = readManifest(path.Join(r, manifestFile), r) || found
	}
	if !found && !force {
		entries, _ := os.ReadDir(dir)
		for _, e := range entries {
			if e.Name() != ".git" {
				return nil, nil, fmt.Errorf("%s is not empty and was not generated by gitopsify; use --force to write into it", dir)
			}
		}
	}

	for _, p := range paths {
		if err := root.MkdirAll(path.Dir(p), 0o755); err != nil {
			return nil, nil, err
		}
		mode := os.FileMode(0o644)
		switch {
		case strings.HasPrefix(p, ".secrets/") || strings.Contains(p, "/.secrets/"):
			mode = 0o600
		case strings.HasSuffix(p, ".sh"):
			mode = 0o755
		}
		if err := root.WriteFile(p, t.files[p], mode); err != nil {
			return nil, nil, err
		}
		written = append(written, p)
	}
	current := map[string]bool{}
	for _, p := range paths {
		current[p] = true
	}
	var stale []string
	for p := range prev {
		if !current[p] {
			stale = append(stale, p)
		}
	}
	sort.Strings(stale)
	for _, p := range stale {
		if err := root.Remove(p); err == nil {
			removed = append(removed, p)
			removeEmptyParents(root, path.Dir(p))
		}
	}
	for _, r := range t.roots {
		var own []string
		for _, p := range paths {
			if rel, ok := strings.CutPrefix(p, r+"/"); ok {
				own = append(own, rel)
			}
		}
		if err := root.MkdirAll(path.Join(r, path.Dir(manifestFile)), 0o755); err != nil {
			return nil, nil, err
		}
		if err := root.WriteFile(path.Join(r, manifestFile), []byte(strings.Join(own, "\n")+"\n"), 0o644); err != nil {
			return nil, nil, err
		}
	}
	if err := root.MkdirAll(path.Dir(manifestFile), 0o755); err != nil {
		return nil, nil, err
	}
	return written, removed, root.WriteFile(manifestFile, []byte(strings.Join(paths, "\n")+"\n"), 0o644)
}

// treePath refuses paths that would leave the output directory or write
// into Git's own files.
func treePath(p string) error {
	if !filepath.IsLocal(filepath.FromSlash(p)) || strings.Contains(p, "\\") {
		return fmt.Errorf("refusing to write %q: it isn't a path inside the output directory", p)
	}
	for _, c := range strings.Split(p, "/") {
		if strings.EqualFold(c, ".git") {
			return fmt.Errorf("refusing to write %q: it is inside .git", p)
		}
	}
	return nil
}

// removeEmptyParents removes dir (slash path inside root) and its parents
// while they are empty.
func removeEmptyParents(root *os.Root, dir string) {
	for dir != "." && dir != "/" && dir != "" {
		f, err := root.Open(dir)
		if err != nil {
			return
		}
		names, err := f.Readdirnames(1)
		f.Close()
		if err == nil || len(names) > 0 {
			return // not empty (or unreadable)
		}
		if root.Remove(dir) != nil {
			return
		}
		dir = path.Dir(dir)
	}
}
